/**
 * Fixture canvas extension. Deliberately shaped like the real
 * `pr-artifact-explorer`: it imports only `@github/copilot-sdk/extension` and
 * `node:` builtins, serves its UI from an ephemeral loopback port behind a
 * per-instance capability token, and returns that URL from `open`.
 *
 * It is a real extension, not a mock: the runner tests fork it exactly as they
 * would fork anything from the catalog.
 */

import { createCanvas, CanvasError, joinSession } from "@github/copilot-sdk/extension";
import { randomBytes } from "node:crypto";
import { createServer } from "node:http";

const instances = new Map();

const session = await joinSession({
	canvases: [
		createCanvas({
			id: "plan-board",
			displayName: "Plan Board",
			description: "A fixture plan board.",
			inputSchema: {
				type: "object",
				properties: { title: { type: "string" }, delayMs: { type: "integer", minimum: 0 } },
				additionalProperties: false,
			},
			actions: [
				{
					name: "add_step",
					description: "Append a step to the plan.",
					inputSchema: { type: "object", properties: { text: { type: "string" } }, required: ["text"] },
					handler: (ctx) => {
						const entry = instances.get(ctx.instanceId);
						if (!entry) throw new CanvasError("no_instance", `Instance "${ctx.instanceId}" is not open.`);
						entry.steps.push(ctx.input.text);
						return { steps: entry.steps.length };
					},
				},
				{
					name: "echo_context",
					description: "Returns the host and session context the callback carried, and the one open was given.",
					handler: (ctx) => {
						const entry = instances.get(ctx.instanceId);
						if (!entry) throw new CanvasError("no_instance", `Instance "${ctx.instanceId}" is not open.`);
						return { host: ctx.host ?? null, session: ctx.session ?? null, atOpen: entry.openContext };
					},
				},
				{
					name: "needs_auth",
					description: "Always fails, to exercise CanvasError propagation.",
					handler: () => {
						throw new CanvasError("github_auth_required", "No usable account was found.");
					},
				},
				{
					name: "crash",
					description: "Exits the process, to exercise host recovery from a dead extension.",
					handler: () => {
						process.exit(9);
					},
				},
				{
					name: "flood",
					description: "Returns an oversized payload, to exercise host-side result capping.",
					handler: () => ({ rows: Array.from({ length: 4000 }, (_, i) => `row-${i}-padding-padding`) }),
				},
				{
					name: "leak_stdout",
					description: "Writes a stray line to stdout, to exercise stray reporting.",
					handler: () => {
						console.log("stray diagnostic from the extension");
						return { wrote: true };
					},
				},
			],
			open: async (ctx) => {
				// `delayMs` lets a test cancel or time out an open that is genuinely in
				// flight, rather than racing an instant one.
				const delayMs = ctx.input?.delayMs ?? 0;
				if (delayMs > 0) await new Promise((resolve) => setTimeout(resolve, delayMs));
				const token = randomBytes(32).toString("base64url");
				const steps = [];
				const server = createServer((req, res) => {
					const url = new URL(req.url ?? "/", "http://127.0.0.1");
					if (url.searchParams.get("token") !== token) {
						res.writeHead(403, { "Content-Type": "text/plain" });
						res.end("forbidden");
						return;
					}
					res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
					res.end(`<!doctype html><title>Plan Board</title><p>${steps.length} steps`);
				});
				await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
				const { port } = server.address();
				instances.set(ctx.instanceId, {
					server,
					token,
					steps,
					openContext: { host: ctx.host ?? null, session: ctx.session ?? null },
				});
				await session.log(`opened ${ctx.instanceId} cwd=${ctx.session?.workingDirectory ?? "none"}`);
				return {
					url: `http://127.0.0.1:${port}/?token=${token}`,
					title: "Plan Board",
					status: "fixture",
				};
			},
			onClose: async (ctx) => {
				const entry = instances.get(ctx.instanceId);
				// Reported either way: a close for an instance the extension never finished
				// opening is exactly the abandon path, and a test needs to see it arrive.
				// stdout is the protocol channel, so session.log is the observable route.
				await session.log(
					`closed ${ctx.instanceId} (known=${entry !== undefined}) cwd=${ctx.session?.workingDirectory ?? "none"}`,
				);
				if (!entry) return;
				instances.delete(ctx.instanceId);
				await new Promise((resolve) => entry.server.close(resolve));
			},

