   HooCode Design System — Colors & Type
   ----------------------------------------------------------------------------
   HooCode is a deterministic terminal coding agent (a fork of pi-mono).
   Its "design system" is a TUI: everything is monospaced text painted with
   ANSI colors on a terminal grid. These tokens are the faithful HTML/CSS
   translation of the agent's two built-in themes (dark.json + light.json),
   so prototypes and mocks render with the exact terminal palette.

   Source of truth:
   packages/coding-agent/src/modes/interactive/theme/{dark,light}.json
   ============================================================================ */

/* ---------------------------------------------------------------------------
   0. BRAND FONTS — self-hosted (uploaded). Both are genuine terminal/coding
   monospaced families. JetBrains Mono is the primary UI/body face; MesloLGS NF
   (a Menlo-derived Nerd Font, the quintessential terminal font) backs it and
   is used for the wordmark/banner via --font-terminal. url() paths resolve
   relative to THIS file (project root), so every importer gets them.
   --------------------------------------------------------------------------- */
@font-face { font-family: "JetBrains Mono"; src: url("fonts/JetBrainsMono-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: "JetBrains Mono"; src: url("fonts/JetBrainsMono-Italic.ttf") format("truetype"); font-weight: 400; font-style: italic; font-display: swap; }
@font-face { font-family: "JetBrains Mono"; src: url("fonts/JetBrainsMono-Medium.ttf") format("truetype"); font-weight: 500; font-style: normal; font-display: swap; }
@font-face { font-family: "JetBrains Mono"; src: url("fonts/JetBrainsMono-SemiBold.ttf") format("truetype"); font-weight: 600; font-style: normal; font-display: swap; }
@font-face { font-family: "JetBrains Mono"; src: url("fonts/JetBrainsMono-Bold.ttf") format("truetype"); font-weight: 700; font-style: normal; font-display: swap; }

@font-face { font-family: "MesloLGS NF"; src: url("fonts/MesloLGSNF-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: "MesloLGS NF"; src: url("fonts/MesloLGSNF-Italic.ttf") format("truetype"); font-weight: 400; font-style: italic; font-display: swap; }
@font-face { font-family: "MesloLGS NF"; src: url("fonts/MesloLGSNF-Bold.ttf") format("truetype"); font-weight: 700; font-style: normal; font-display: swap; }
@font-face { font-family: "MesloLGS NF"; src: url("fonts/MesloLGSNF-BoldItalic.ttf") format("truetype"); font-weight: 700; font-style: italic; font-display: swap; }

/* ---------------------------------------------------------------------------
   1. BASE PALETTE — raw named colors (the theme `vars` block)
   The dark theme is the canonical default. Names mirror the theme JSON.
   --------------------------------------------------------------------------- */
:root {
  /* Dark theme raw vars */
  --hc-cyan:        #00d7ff; /* bright info / borderAccent */
  --hc-blue:        #5f87ff; /* structural border */
  --hc-green:       #b5bd68; /* success, diff added */
  --hc-red:         #cc6666; /* error, diff removed */
  --hc-yellow:      #ffff00; /* warning, line numbers */
  --hc-gray:        #808080; /* muted text */
  --hc-dim-gray:    #666666; /* dim / secondary */
  --hc-dark-gray:   #505050; /* borderMuted, thinking off */
  --hc-accent:      #8abeb7; /* signature aqua accent */

  /* Background fills */
  --hc-selected-bg:     #3a3a4a;
  --hc-user-msg-bg:     #343541;
  --hc-tool-pending-bg: #282832;
  --hc-tool-success-bg: #283228;
  --hc-tool-error-bg:   #3c2828;
  --hc-custom-msg-bg:   #2d2838;

  /* Surfaces (export/HTML rendering of the terminal) */
  --hc-page-bg:   #18181e; /* terminal canvas */
  --hc-card-bg:   #1e1e24; /* panel / sidebar */
  --hc-info-bg:   #3c3728; /* highlighted info strip */

  /* Default foreground (terminal default fg, dark) */
  --hc-text:      #e5e5e7;
}

/* ---------------------------------------------------------------------------
   2. SEMANTIC TOKENS — how the agent actually uses color
   These are the names you reach for when building UI.
   --------------------------------------------------------------------------- */
:root {
  --fg:              var(--hc-text);      /* primary text */
  --fg-muted:        var(--hc-gray);      /* labels, secondary */
  --fg-dim:          var(--hc-dim-gray);  /* tertiary, paths, hints */
  --fg-thinking:     var(--hc-gray);      /* reasoning traces (italic) */

  --accent:          var(--hc-accent);    /* file paths, list bullets, mode tag, cursor */
  --border:          var(--hc-blue);      /* rules, focused field outline */
  --border-accent:   var(--hc-cyan);      /* headings, model name, branch summary */
  --border-muted:    var(--hc-dark-gray); /* editor frame */

  --success:         var(--hc-green);     /* done, added, [x] */
  --error:           var(--hc-red);       /* failed, removed, aborted */
  --warning:         var(--hc-yellow);    /* in-progress, line ranges, truncation notes */

  /* Message & tool surfaces */
  --user-msg-bg:     var(--hc-user-msg-bg);
  --tool-pending-bg: var(--hc-tool-pending-bg);
  --tool-success-bg: var(--hc-tool-success-bg);
  --tool-error-bg:   var(--hc-tool-error-bg);
  --custom-msg-bg:   var(--hc-custom-msg-bg);
  --custom-msg-label:#9575cd;             /* skill / hook / compaction label (purple) */
  --selected-bg:     var(--hc-selected-bg);
  --tool-output:     var(--hc-gray);

  /* Markdown */
  --md-heading:      #f0c674;             /* warm gold */
  --md-link:         #81a2be;             /* desaturated blue */
  --md-link-url:     var(--hc-dim-gray);
  --md-code:         var(--hc-accent);
  --md-code-block:   var(--hc-green);
  --md-quote:        var(--hc-gray);
  --md-quote-border: var(--hc-gray);
  --md-hr:           var(--hc-gray);
  --md-list-bullet:  var(--hc-accent);

  /* Diff */
  --diff-added:      var(--hc-green);
  --diff-removed:    var(--hc-red);
  --diff-context:    var(--hc-gray);

  /* Syntax highlighting (VS Code Dark+ lineage) */
  --syntax-comment:  #6A9955;
  --syntax-keyword:  #569CD6;
  --syntax-function: #DCDCAA;
  --syntax-variable: #9CDCFE;
  --syntax-string:   #CE9178;
  --syntax-number:   #B5CEA8;
  --syntax-type:     #4EC9B0;
  --syntax-operator: #D4D4D4;
  --syntax-punct:    #D4D4D4;

