//! Port of hoocode `utils/oauth/types.ts` (v0.5.89).

use std::future::Future;
use std::pin::Pin;

use cortexcode_ai_types::{AbortSignal, Model};
use serde::{Deserialize, Serialize};

/// A boxed, sendable future.
pub type BoxFuture<'a, T> = Pin<Box<dyn Future<Output = T> + Send + 'a>>;

/// `OAuthCredentials`: `{refresh, access, expires, [key]: unknown}`. Extra
/// provider fields (e.g. Copilot's `enterpriseUrl`) sit next to the three
/// known ones, as in hoocode's `auth.json`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct OAuthCredentials {
    pub refresh: String,
    pub access: String,
    /// Unix milliseconds after which `access` is treated as expired (the
    /// providers already subtract a 5 minute margin).
    pub expires: i64,
    #[serde(flatten)]
    pub extra: serde_json::Map<String, serde_json::Value>,
}

impl OAuthCredentials {
    /// Credentials without extra fields.
    pub fn new(refresh: impl Into<String>, access: impl Into<String>, expires: i64) -> Self {
        Self {
            refresh: refresh.into(),
            access: access.into(),
            expires,
            extra: serde_json::Map::new(),
        }
    }

    /// `Date.now() >= expires`.
    pub fn is_expired(&self, now_millis: i64) -> bool {
        now_millis >= self.expires
    }

    /// An extra string field.
    pub fn extra_str(&self, key: &str) -> Option<&str> {
        self.extra.get(key).and_then(|v| v.as_str())
    }
}

/// `OAuthPrompt`.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OAuthPrompt {
    pub message: String,
    pub placeholder: Option<String>,
    pub allow_empty: bool,
}

/// `OAuthAuthInfo`: where the user authenticates.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OAuthAuthInfo {
    pub url: String,
    pub instructions: Option<String>,
}

/// `OAuthSelectOption`.
#[derive(Debug, Clone, PartialEq)]
pub struct OAuthSelectOption {
    pub id: String,
    pub label: String,
}

/// `OAuthSelectPrompt`.
#[derive(Debug, Clone, PartialEq)]
pub struct OAuthSelectPrompt {
    pub message: String,
    pub options: Vec<OAuthSelectOption>,
}

/// `OAuthLoginCallbacks`: how a login flow talks to the user.
pub trait OAuthLoginCallbacks: Send + Sync {
    /// `onAuth`: show the URL (and instructions) to open.
    fn on_auth(&self, info: OAuthAuthInfo);

    /// `onPrompt`: ask for a line of input.
    fn on_prompt(&self, prompt: OAuthPrompt) -> BoxFuture<'_, Result<String, String>>;

    /// `onProgress`.
    fn on_progress(&self, _message: &str) {}

    /// `onManualCodeInput`: `None` when the caller cannot take a pasted
    /// code while the callback server waits.
    fn on_manual_code_input(&self) -> Option<BoxFuture<'_, Result<String, String>>> {
        None
    }

    /// `onSelect`: the chosen option id, `None` on cancel.
    fn on_select(&self, _prompt: OAuthSelectPrompt) -> BoxFuture<'_, Option<String>> {
        Box::pin(async { None })
    }

    /// `signal`.
    fn signal(&self) -> Option<AbortSignal> {
        None
    }
}

/// `OAuthProviderInterface`.
pub trait OAuthProvider: Send + Sync {
    fn id(&self) -> &str;
    fn name(&self) -> &str;

    /// `usesCallbackServer`.
    fn uses_callback_server(&self) -> bool {
        false
    }

    /// Run the login flow; the credentials are for the caller to persist.
    fn login<'a>(
        &'a self,
        callbacks: &'a dyn OAuthLoginCallbacks,
    ) -> BoxFuture<'a, Result<OAuthCredentials, String>>;

//! Request-shape tests. The TS tests capture the payload handed to the
//! `openai` SDK; here the same pipeline (`streamSimple` option mapping,
//! `getCompat`, `resolveCacheRetention`, `buildParams`) runs without HTTP.
//!
//! Ported from `openai-completions-cache-control-format.test.ts`,
//! `-empty-tools.test.ts`, `-prompt-cache.test.ts`, `-prompt-suffix.test.ts`,
//! `-thinking-as-text.test.ts`, `-tool-result-images.test.ts` and the payload
//! cases of `-tool-choice.test.ts` (hoocode v0.5.89).

use super::*;
use cortexcode_ai_types::{
    AssistantMessage, ImageContent, StopReason, TextContent, ThinkingContent, ToolCallContent,
    ToolResultMessage, UserMessage,
};
use std::sync::{Mutex, MutexGuard};

/// Serializes tests that read or set the cache-retention env vars.
pub(crate) fn env_lock() -> MutexGuard<'static, ()> {
    static LOCK: Mutex<()> = Mutex::new(());
    LOCK.lock().unwrap_or_else(|e| e.into_inner())
}

pub(crate) fn catalog(provider: &str, id: &str) -> Model {
    cortexcode_ai_models::get_model(provider, id)
        .unwrap_or_else(|| panic!("{provider}/{id} in catalog"))
        .clone()
}

/// `const { compat: _compat, ...baseModel } = getModel(...)` with
/// `api: "openai-completions"`.
pub(crate) fn completions(provider: &str, id: &str) -> Model {
    let mut m = catalog(provider, id);
    m.compat = None;
    m.api = "openai-completions".into();
    m
}

fn custom_model(provider: &str, base_url: &str, reasoning: bool, compat: Option<Value>) -> Model {
    Model {
        id: "custom".into(),
        name: "Custom".into(),
        api: "openai-completions".into(),
        provider: provider.into(),
        base_url: base_url.into(),
        reasoning,
        thinking_level_map: None,
        input: vec!["text".into()],
        cost: Default::default(),
        context_window: 128_000,
        max_tokens: 32_000,
        headers: None,
        compat,
    }
}

/// `{ role: "user", content: text }`: string content, as the TS tests use.
pub(crate) fn user(text: &str) -> Message {
    Message::User(UserMessage {
        content: text.into(),
        timestamp: 1,
    })
}

fn tool(name: &str) -> Tool {
    Tool {
        defer_loading: None,
        name: name.into(),
        description: format!("{name} tool"),
        parameters: json!({
            "type": "object",
            "properties": {"ok": {"type": "boolean"}},
            "required": ["ok"]
        }),
    }
}

/// The payload `streamSimple` would send.
fn payload(model: &Model, context: &Context, options: SimpleStreamOptions) -> Value {
    let options = simple_options(model, &options, "test".into());
    let compat = get_compat(model);
    let retention = cortexcode_ai_util::resolve_cache_retention(options.cache_retention);
    build_params(model, context, &options, &compat, &retention)
}

fn with_env<T>(value: Option<&str>, f: impl FnOnce() -> T) -> T {
    let _lock = env_lock();
    let saved: Vec<_> = ["CORTEXCODE_CACHE_RETENTION", "HOOCODE_CACHE_RETENTION"]
        .iter()
        .map(|k| (*k, std::env::var(k).ok()))
        .collect();
    std::env::remove_var("CORTEXCODE_CACHE_RETENTION");
    match value {
        Some(v) => std::env::set_var("HOOCODE_CACHE_RETENTION", v),
        None => std::env::remove_var("HOOCODE_CACHE_RETENTION"),
    }
    let out = f();
    for (k, v) in saved {
        match v {
            Some(v) => std::env::set_var(k, v),
            None => std::env::remove_var(k),
        }
    }
    out
}

// --- openai-completions-cache-control-format.test.ts ---

fn cache_context() -> Context {
    Context::new(
        "System prompt".into(),
        vec![user("Hello")],
        vec![Tool {
            defer_loading: None,
            name: "read".into(),
            description: "Read a file".into(),
            parameters: json!({"type": "object", "properties": {"path": {"type": "string"}}, "required": ["path"]}),
        }],
    )
}

