        assert_eq!(build_initial_message(&mut Vec::new(), Some(""), None), None);
    }

    #[test]
    fn piped_stdin_is_trimmed_and_empty_is_none() {
        assert_eq!(normalize_piped_stdin("  hi \n").as_deref(), Some("hi"));

