fn join(regexps: &[String]) -> String {
    let mut num_captures = 0usize;
    let mut out_parts = Vec::new();
    for regex in regexps {
        num_captures += 1;
        let offset = num_captures;
        let chars: Vec<char> = regex.chars().collect();
        let mut out = String::new();
        let mut i = 0;
