                    // pattern fails here and the scan moves on.
                    let mut j = i + 1;
                    let mut closed = false;
                    while j < chars.len() {
                        match chars[j] {
                            '\\' if j + 1 < chars.len() => j += 2,
                            '\\' => break,
                            ']' => {
                                closed = true;
                                break;
                            }
                            _ => j += 1,
                        }
                    }
                    if closed {
                        out.extend(&chars[i..=j]);
                        i = j + 1;
                    } else {
                        out.push('[');
                        i += 1;
                    }
                }
                '(' => {
                    if chars.get(i + 1) == Some(&'?') {
                        out.push_str("(?");
                        i += 2;
                    } else {
                        out.push('(');
